grid:


























































































		&XMLUserDefinedFields;




























			&XMLUserDefinedViews;



























declare @message nvarchar(4000)
select @message = ''
&VisibleFieldGridShowing;
select @message as message
return







declare @udfPaymentControl char(1)
select @udfPaymentControl = rtrim(val) from options where name = 'm_gl_tt'
select @udfPaymentControl = isnull(@udfPaymentControl, '0')
select 'this._udfPaymentControl=' + @udfPaymentControl + ';load$GridReport$Item(this);' as message
return







			function load$GridReport$Item(b) {
		var a = document._masterGrid,
		c = a._dvTransactionType ? a._dvTransactionType: "1";
		set$View$VoucherType(a, c);
		udf$View$PaymentControl(b);
		b.add_onRender(on$GridReport$Render$Item)
}
			&MultiViewer.GridView.Render;function udf$View$PaymentControl(a) {
		var c = ["ma_tt", "so_ct0", "ngay_ct0"];
		a._suspendLayout();
		for (var b = 0; b < c.length; b++) set$ColumnVisible(a, a._getColumnOrder($func.trim(c[b])), a._udfPaymentControl);
		a._resumeLayout()
}
function set$View$VoucherType(c, a) {
		var b = c._detailGrid,
		e = ["so_ct_tt2", "ngay_ct_tt2", "so_ct_tt3", "ngay_ct_tt3"];
		if (!a) a = $func.trim(c._getItemValue(c._activeRow, c._getColumnOrder("loai_ct")));
		if (!a) a = "1";
		var f = ["2", "3", "4"].indexOf(a) >= 0;
		b._suspendLayout();
		for (var d = 0; d < e.length; d++) set$ColumnVisible(b, b._getColumnOrder($func.trim(e[d])), f);
		b._resumeLayout()
}







declare @$baseCurrency varchar(32) = ''
select top 0 stt_rec, ngay_ct, ma_nt into #$cttt20 from cttt20
select top 0 stt_rec, ngay_ct, ma_nt into #$cttt30 from cttt30
select top 0 tk into #$ar from dmtk
select top 0 tk into #$ap from dmtk

select top 0 @@fieldExternal
	from @@prime$partition$current a
		left join dmtk b on a.tk = b.tk
		left join dmkh c on a.ma_kh = c.ma_kh
		&ESG.queryLoadingHoverField;
		left join #$cttt20 d on a.stt_rec_tt2 = d.stt_rec
		left join #$cttt30 e on a.stt_rec_tt3 = e.stt_rec
		left join #$ar f on a.tk = f.tk
		left join #$ap g on a.tk = g.tk






				&MultiViewer.Check;

declare @$q nvarchar(4000), @$c_013 varchar(32), @$baseCurrency varchar(32), @$arAccount varchar(512), @$apAccount varchar(512), @$accKey nvarchar(4000)

select top 1 @$baseCurrency = rtrim(ltrim(val)) from options where name = 'm_ma_nt0'
select top 1 @$arAccount = rtrim(ltrim(val)) from options where name = 'm_tk_cn_pth'
select top 1 @$apAccount = rtrim(ltrim(val)) from options where name = 'm_tk_cn_ptr'
select top 1 @$c_013 = rtrim(ltrim(val)) from options where name = 'c_013'

select top 1 @$baseCurrency = rtrim(ltrim(val)) from options where name = 'm_ma_nt0'

select stt_rec, ngay_ct, ma_nt into #$cttt20 from cttt20
select stt_rec, ngay_ct, ma_nt into #$cttt30 from cttt30
select top 0 tk into #$ar from dmtk
select top 0 tk into #$ap from dmtk

exec dbo.FastBusiness$App$GetAccountKey 'tk', 'inlist', @$arAccount, '#$ar', @@userID, @@admin, @$accKey output
if isnull(@$c_013, '0') = '1' begin
	select @$q = 'insert into #$ar select tk from dmtk' + case when @$accKey is not null then ' where ' + @$accKey else '' end
	exec sp_executesql @$q
end
exec dbo.FastBusiness$App$GetAccountKey 'tk', 'inlist', @$apAccount, '#$ap', @@userID, @@admin, @$accKey output
if isnull(@$c_013, '0') = '1' begin
	select @$q = 'insert into #$ap select tk from dmtk' + case when @$accKey is not null then ' where ' + @$accKey else '' end
	exec sp_executesql @$q
end

select @@fieldExternal
	from @@prime$partition$current a
		left join dmtk b on a.tk = b.tk left join dmkh c on a.ma_kh = c.ma_kh
		&ESG.queryLoadingHoverField;
		left join #$cttt20 d on a.stt_rec_tt2 = d.stt_rec left join #$cttt30 e on a.stt_rec_tt3 = e.stt_rec
		left join #$ar f on a.tk = f.tk left join #$ap g on a.tk = g.tk
	where a.stt_rec = @stt_rec
	order by a.stt_rec, a.line_nbr





	&MultiViewer.Toolbar;
